// Using holder sets in recipes
// In JSON: { "type": "neoforge:any", "values": ["mod:item1", "mod:item2"] }

// Programmatic
public static HolderSet<Block> anyOf(Holder<Block>... blocks) {
    return new AnyHolderSet(List.of(blocks));
}

public static HolderSet<Block> notOf(Holder<Block> block) {
    return new NotHolderSet(block);
}
